// Wrapper simples de fetch pra API REST do Supabase (PostgREST) — sem depender de pacote npm externo
async function sbFetch(path, { method = "GET", body, accessToken, prefer } = {}) {
  const headers = {
    "apikey": SUPABASE_ANON_KEY,
    "Authorization": `Bearer ${accessToken || SUPABASE_ANON_KEY}`,
    "Content-Type": "application/json",
  };
  if (prefer) headers["Prefer"] = prefer;
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    method, headers, body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Supabase ${method} ${path} falhou: ${res.status} ${errText}`);
  }
  if (res.status === 204) return null;
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}

async function sbSignIn(email, password) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
    method: "POST",
    headers: { "apikey": SUPABASE_ANON_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "falha no login");
  return data; // { access_token, refresh_token, user }
}

async function sbRpc(fn, args, accessToken) {
  return sbFetch(`rpc/${fn}`, { method: "POST", body: args, accessToken });
}

async function createPaymentLink({ handle, items, orderNsu, redirectUrl }) {
  const res = await fetch(`${SUPABASE_URL}/functions/v1/create-payment-link`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "apikey": SUPABASE_ANON_KEY },
    body: JSON.stringify({ handle, items, order_nsu: orderNsu, redirect_url: redirectUrl }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data?.error ? JSON.stringify(data.error) : "falha ao gerar link de pagamento");
  return data; // { url: "..." }
}

// mapeamento entre o formato do banco (snake_case) e o formato usado no app
function mapDbProduct(row) {
  return {
    id: row.id, name: row.name, desc: row.description, price: Number(row.price), stock: row.stock,
    frozen: row.frozen, category: row.category, lote: row.lote, active: row.active,
    images: row.images || [], tags: row.tags || [],
  };
}
function toDbProduct(p) {
  return {
    id: p.id, name: p.name, description: p.desc, price: Number(p.price) || 0, stock: Number(p.stock) || 0,
    frozen: !!p.frozen, category: p.category, lote: p.lote, active: p.active !== false,
    images: p.images || [], tags: p.tags || [],
  };
}
function mapDbConfig(row) {
  return {
    heroTitle: row.hero_title, heroSubtitle: row.hero_subtitle, loteAtual: row.lote_atual,
    whatsappNumber: row.whatsapp_number, deliveryZones: row.delivery_zones || [],
    pedidoMinimo: Number(row.pedido_minimo) || 0, mostrarEstoque: !!row.mostrar_estoque,
    lojaAberta: row.loja_aberta !== false, horarios: row.horarios || [],
    diasEntrega: row.dias_entrega || [], janelasHorario: row.janelas_horario || [],
    mensagemWhatsapp: row.mensagem_whatsapp || DEFAULT_MENSAGEM_WHATSAPP,
    infinitepayHandle: row.infinitepay_handle || "",
    entregaAtiva: row.entrega_ativa !== false,
    retiradaAtiva: row.retirada_ativa !== false,
  };
}
function toDbConfig(c) {
  return {
    id: 1, hero_title: c.heroTitle, hero_subtitle: c.heroSubtitle, lote_atual: c.loteAtual,
    whatsapp_number: c.whatsappNumber, delivery_zones: c.deliveryZones || [],
    pedido_minimo: Number(c.pedidoMinimo) || 0, mostrar_estoque: !!c.mostrarEstoque,
    loja_aberta: c.lojaAberta !== false, horarios: c.horarios || [],
    dias_entrega: c.diasEntrega || [], janelas_horario: c.janelasHorario || [],
    mensagem_whatsapp: c.mensagemWhatsapp || DEFAULT_MENSAGEM_WHATSAPP,
    infinitepay_handle: c.infinitepayHandle || "",
    entrega_ativa: c.entregaAtiva !== false,
    retirada_ativa: c.retiradaAtiva !== false,
  };
}
