const DEFAULT_HERO_TITLE = "Produção artesanal. Lotes pequenos. Entrega marcada.";
const DEFAULT_HERO_SUBTITLE = "Peça pelo carrinho abaixo — o pedido segue direto para o WhatsApp já organizado. Itens congelados: combine um horário em que alguém esteja em casa.";

// ============================================================
export default function App() {
  const [view, setView] = useState("loja");
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState({});
  const [accessToken, setAccessToken] = useState(null);
  const [loginEmail, setLoginEmail] = useState("");
  const [loginPassword, setLoginPassword] = useState("");
  const [loginError, setLoginError] = useState("");
  const [loginLoading, setLoginLoading] = useState(false);
  const [lastMessage, setLastMessage] = useState("");
  const [paymentLink, setPaymentLink] = useState(null);
  const [heroTitle, setHeroTitle] = useState(DEFAULT_HERO_TITLE);
  const [heroSubtitle, setHeroSubtitle] = useState(DEFAULT_HERO_SUBTITLE);
  const [loteAtual, setLoteAtual] = useState(DEFAULT_LOTE);
  const [whatsappNumber, setWhatsappNumber] = useState(DEFAULT_WHATSAPP_NUMBER);
  const [deliveryZones, setDeliveryZones] = useState(DEFAULT_DELIVERY_ZONES);
  const [pedidoMinimo, setPedidoMinimo] = useState(0);
  const [mostrarEstoque, setMostrarEstoque] = useState(false);
  const [lojaAberta, setLojaAberta] = useState(true);
  const [horarios, setHorarios] = useState(DEFAULT_HORARIOS);
  const [diasEntrega, setDiasEntrega] = useState(DEFAULT_DIAS_ENTREGA);
  const [janelasHorario, setJanelasHorario] = useState(DEFAULT_JANELAS_HORARIO);
  const [mensagemWhatsapp, setMensagemWhatsapp] = useState(DEFAULT_MENSAGEM_WHATSAPP);
  const [infinitepayHandle, setInfinitepayHandle] = useState("");
  const [entregaAtiva, setEntregaAtiva] = useState(true);
  const [retiradaAtiva, setRetiradaAtiva] = useState(true);

  useEffect(() => {
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Caveat:wght@600;700&family=Courier+Prime:wght@400;700&display=swap";
    document.head.appendChild(link);
    return () => document.head.removeChild(link);
  }, []);

  useEffect(() => {
    (async () => {
      try {
        const rows = await sbFetch("products?select=*&order=created_at.asc");
        setProducts((rows || []).map(mapDbProduct));
      } catch (e) {
        console.error("Falha ao carregar produtos do Supabase", e);
      } finally {
        setLoading(false);
      }
    })();
    (async () => {
      try {
        const rows = await sbFetch("store_config?id=eq.1&select=*");
        if (rows && rows.length > 0) {
          const cfg = mapDbConfig(rows[0]);
          setHeroTitle(cfg.heroTitle || DEFAULT_HERO_TITLE);
          setHeroSubtitle(cfg.heroSubtitle || DEFAULT_HERO_SUBTITLE);
          setLoteAtual(cfg.loteAtual || DEFAULT_LOTE);
          setWhatsappNumber(cfg.whatsappNumber || DEFAULT_WHATSAPP_NUMBER);
          setDeliveryZones(cfg.deliveryZones && cfg.deliveryZones.length > 0 ? cfg.deliveryZones : DEFAULT_DELIVERY_ZONES);
          setPedidoMinimo(cfg.pedidoMinimo);
          setMostrarEstoque(cfg.mostrarEstoque);
          setLojaAberta(cfg.lojaAberta);
          setHorarios(cfg.horarios && cfg.horarios.length > 0 ? cfg.horarios : DEFAULT_HORARIOS);
          setDiasEntrega(cfg.diasEntrega);
          setJanelasHorario(cfg.janelasHorario);
          setMensagemWhatsapp(cfg.mensagemWhatsapp);
          setInfinitepayHandle(cfg.infinitepayHandle);
          setEntregaAtiva(cfg.entregaAtiva);
          setRetiradaAtiva(cfg.retiradaAtiva);
        }
      } catch (e) {
        console.error("Falha ao carregar configurações do Supabase", e);
      }
    })();
  }, []);

  const saveConfig = async (next) => {
    setHeroTitle(next.heroTitle);
    setHeroSubtitle(next.heroSubtitle);
    setLoteAtual(next.loteAtual);
    setWhatsappNumber(next.whatsappNumber);
    setDeliveryZones(next.deliveryZones);
    setPedidoMinimo(next.pedidoMinimo);
    setMostrarEstoque(next.mostrarEstoque);
    setLojaAberta(next.lojaAberta);
    setHorarios(next.horarios);
    setDiasEntrega(next.diasEntrega);
    setJanelasHorario(next.janelasHorario);
    setMensagemWhatsapp(next.mensagemWhatsapp);
    setInfinitepayHandle(next.infinitepayHandle);
    setEntregaAtiva(next.entregaAtiva);
    setRetiradaAtiva(next.retiradaAtiva);
    try {
      await sbFetch("store_config", {
        method: "POST", accessToken, prefer: "resolution=merge-duplicates,return=minimal",
        body: toDbConfig(next),
      });
    } catch (e) {
      console.error("Falha ao salvar configurações no Supabase", e);
    }
  };

  const saveProducts = async (next) => {
    const previousIds = products.map((p) => p.id);
    const nextIds = next.map((p) => p.id);
    const removedIds = previousIds.filter((id) => !nextIds.includes(id));
    setProducts(next);
    try {
      if (next.length > 0) {
        await sbFetch("products", {
          method: "POST", accessToken, prefer: "resolution=merge-duplicates,return=minimal",
          body: next.map(toDbProduct),
        });
      }
      for (const id of removedIds) {
        await sbFetch(`products?id=eq.${id}`, { method: "DELETE", accessToken });
      }
    } catch (e) {
      console.error("Falha ao salvar catálogo no Supabase", e);
    }
  };

  const login = async () => {
    setLoginError("");
    setLoginLoading(true);
    try {
      const data = await sbSignIn(loginEmail.trim(), loginPassword);
      setAccessToken(data.access_token);
      setLoginPassword("");
    } catch (e) {
      setLoginError(e.message || "não foi possível entrar");
    } finally {
      setLoginLoading(false);
    }
  };
  const logout = () => {
    setAccessToken(null);
    setView("loja");
  };

  const cartItems = useMemo(() => {
    return Object.entries(cart)
      .filter(([, qty]) => qty > 0)
      .map(([id, qty]) => ({ ...products.find((p) => p.id === id), qty }))
      .filter((i) => i.id);
  }, [cart, products]);

  const cartCount = cartItems.reduce((s, i) => s + i.qty, 0);
  const cartTotal = cartItems.reduce((s, i) => s + i.qty * i.price, 0);

  const addToCart = (id) => {
    const product = products.find((p) => p.id === id);
    const current = cart[id] || 0;
    if (!product || current >= product.stock) return;
    setCart({ ...cart, [id]: current + 1 });
  };
  const decFromCart = (id) => {
    const current = cart[id] || 0;
    if (current <= 1) {
      const next = { ...cart };
      delete next[id];
      setCart(next);
    } else {
      setCart({ ...cart, [id]: current - 1 });
    }
  };
  const removeFromCart = (id) => {
    const next = { ...cart };
    delete next[id];
    setCart(next);
  };

  return (
    <div style={{ background: C.paper, color: C.ink, minHeight: "100vh", fontFamily: "'Courier Prime', monospace" }}>
      <style>{`
        * { box-sizing: border-box; }
        ::selection { background: ${C.ink}; color: ${C.paper}; }
        .hand { font-family: 'Caveat', cursive; }
        button { font-family: inherit; cursor: pointer; }
        input, textarea, select { font-family: inherit; }
        body { background: ${C.paper}; }
        @keyframes fadeUp { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
        .fade-up { animation: fadeUp .35s ease both; }
      `}</style>

      <Header view={view} setView={setView} cartCount={cartCount} loteAtual={loteAtual} />

      <main className="max-w-5xl mx-auto px-4 pb-24">
        {view === "loja" && (
          <Store products={products} loading={loading} cart={cart} addToCart={addToCart} setView={setView} cartCount={cartCount} heroTitle={heroTitle} heroSubtitle={heroSubtitle} loteAtual={loteAtual} mostrarEstoque={mostrarEstoque} />
        )}
        {view === "carrinho" && (
          <Cart
            cartItems={cartItems}
            addToCart={addToCart}
            decFromCart={decFromCart}
            removeFromCart={removeFromCart}
            cartTotal={cartTotal}
            setView={setView}
            pedidoMinimo={pedidoMinimo}
          />
        )}
        {view === "checkout" && (
          <Checkout
            cartItems={cartItems}
            cartTotal={cartTotal}
            setView={setView}
            setLastMessage={setLastMessage}
            products={products}
            setCart={setCart}
            loteAtual={loteAtual}
            whatsappNumber={whatsappNumber}
            deliveryZones={deliveryZones}
            pedidoMinimo={pedidoMinimo}
            diasEntrega={diasEntrega}
            janelasHorario={janelasHorario}
            mensagemWhatsapp={mensagemWhatsapp}
            infinitepayHandle={infinitepayHandle}
            entregaAtiva={entregaAtiva}
            retiradaAtiva={retiradaAtiva}
            setPaymentLink={setPaymentLink}
            onStockDecremented={(decrements) => {
              setProducts((prev) => prev.map((p) => {
                const dec = decrements.find((d) => d.id === p.id);
                return dec ? { ...p, stock: Math.max(0, p.stock - dec.qty) } : p;
              }));
            }}
          />
        )}
        {view === "sucesso" && <Sucesso message={lastMessage} setView={setView} paymentLink={paymentLink} whatsappNumber={whatsappNumber} />}
        {view === "admin" && !accessToken && (
          <AdminLogin
            email={loginEmail} setEmail={setLoginEmail}
            password={loginPassword} setPassword={setLoginPassword}
            error={loginError} loading={loginLoading}
            onSubmit={login}
          />
        )}
        {view === "admin" && accessToken && (
          <Admin products={products} saveProducts={saveProducts} heroTitle={heroTitle} heroSubtitle={heroSubtitle} loteAtual={loteAtual} whatsappNumber={whatsappNumber} deliveryZones={deliveryZones} pedidoMinimo={pedidoMinimo} mostrarEstoque={mostrarEstoque} lojaAberta={lojaAberta} horarios={horarios} diasEntrega={diasEntrega} janelasHorario={janelasHorario} mensagemWhatsapp={mensagemWhatsapp} infinitepayHandle={infinitepayHandle} entregaAtiva={entregaAtiva} retiradaAtiva={retiradaAtiva} saveConfig={saveConfig} accessToken={accessToken} onLogout={logout} />
        )}
      </main>

      <Footer />
    </div>
  );
}

