function Stamp({ children, size = 56, tone = "ink", rotate = -6 }) {
  const bg = tone === "ink" ? C.ink : tone === "red" ? C.red : C.cold;
  return (
    <div style={{
      width: size, height: size, borderRadius: "50%", background: bg, color: C.white,
      display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center",
      transform: `rotate(${rotate}deg)`, flexShrink: 0, boxShadow: "0 2px 5px rgba(0,0,0,0.18)",
      lineHeight: 1.05, padding: 4,
    }}>
      {children}
    </div>
  );
}

